def get_restaurants(rests, cuisines_wanted):
    # Return a dict of cuisine -> list of restaurants
    classified = {c: [] for c in cuisines_wanted}
    others = []

    for r in rests:
        c_str = str(r.get('Cuisines', '')).lower()
        assigned = False
        for c in cuisines_wanted:
            if c.lower() in c_str:
                classified[c].append(r['Name'])
                assigned = True
        if not assigned:
            others.append(r['Name'])

    return classified, others

